const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check all tables for these product names
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();

// Search products table if exists
try {
  const products = db.prepare(\"SELECT * FROM products WHERE name LIKE '%TrailFlex%' OR name LIKE '%Everyday Crew%' OR name LIKE '%Jogger%' OR name LIKE '%Crew Tee%'\").all();
  console.log('Products found:', products);
} catch(e) { console.log('No products table or error:', e.message); }

