  const variants = db.prepare('SELECT * FROM rt_variants').all();
  console.log('\\nAll rt_variants (' + variants.length + ' total):');
  variants.forEach(v => console.log(JSON.stringify(v)));
} catch(e) { console.log('rt_variants error:', e.message); }
"

