const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Search all products for TrailFlex or Crew Tee
const allProducts = db.prepare('SELECT * FROM products').all();
const matches = allProducts.filter(p => 
  p.name && (p.name.toLowerCase().includes('trailflex') || 
             p.name.toLowerCase().includes('jogger') || 
             p.name.toLowerCase().includes('crew tee') ||
             p.name.toLowerCase().includes('everyday crew'))
);
